// 1. Récupération du CV et des deux nouvelles propriétés Notion
const properties = $('Webhook').item.json.body?.data?.properties || {};
const richTextArray = properties.CV?.rich_text || [];

// Extraction propre depuis Get PageID
const company = $('Get PageID').first().json.company || 'company';
const jobTitle = $('Get PageID').first().json.jobTitle || 'job';
const increment = $('Get PageID').first().json.increment || '01';

let mdText = richTextArray.map(block => block.plain_text || '').join('');

// 2. Parser Markdown avec nettoyage du "plain text" parasite
function robustMarkdownToHtml(md) {
  // Suppression des mentions "plain text" ou "plain_text" textuelles injectées par l'agent
  let cleanedMd = md.replace(/plain[\s_]text/gi, '');

  const lines = cleanedMd.split('\n');
  let htmlOutput = [];
  let inList = false;

  for (let line of lines) {
    let trimmed = line.trim();
    if (!trimmed.startsWith('-') && !trimmed.startsWith('*') && inList) {
      htmlOutput.push('</ul>');
      inList = false;
    }
    if (trimmed === '---' || trimmed === '***') {
      htmlOutput.push('<hr />');
      continue;
    }
    if (trimmed.startsWith('>')) {
      let content = line.replace(/^>\s*/, '').trim().replace(/^"(.*)"$/, '$1');
      htmlOutput.push(`<div class="summary-box">	ext;</div>`.replace('text;', content));
      continue;
    }
    if (trimmed.startsWith('# ')) { htmlOutput.push(`<h1>	ext;</h1>`.replace('text;', trimmed.substring(2))); continue; }
    if (trimmed.startsWith('## ')) { htmlOutput.push(`<h2>	ext;</h2>`.replace('text;', trimmed.substring(3))); continue; }
    if (trimmed.startsWith('### ')) { htmlOutput.push(`<h3>	ext;</h3>`.replace('text;', trimmed.substring(4))); continue; }

    if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
      if (!inList) { htmlOutput.push('<ul>'); inList = true; }
      htmlOutput.push(`<li>${trimmed.replace(/^[\-\*]\s*/, '')}</li>`);
      continue;
    }
    if (trimmed !== '') htmlOutput.push(`<p>&line;</p>`.replace('&line;', line));
  }
  if (inList) htmlOutput.push('</ul>');

  let finalBody = htmlOutput.join('\n');
  return finalBody.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
}

// Fonction utilitaire pour nettoyer les caractères spéciaux du futur nom de fichier
function slugify(text) {
  return text
    .toString()
    .toLowerCase()
    .normalize('NFD') // Supprime les accents
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .replace(/\s+/g, '-') // Remplace les espaces par des tirets
    .replace(/[^a-z0-9\-]/g, ''); // Supprime le reste
}

const finalFileName = "javarre-" + slugify(company) + "-" + slugify(jobTitle);

// 3. RECUPERATION CONFIG
let config = { showVersion: false };
try {
  config = JSON.parse($('Read Config from Table').first().json.value);
} catch (e) {}

let compiledBody = robustMarkdownToHtml(mdText);
if (config.showVersion) {
  compiledBody = compiledBody + `<div class="resume-version-footer">v${increment}</div>`;
}

return [
  {
    json: {
      compiledBody: compiledBody,
      pdfFileName: finalFileName
    }
  }
];

// 1. Récupération des données brutes du Webhook
const body = $('Webhook').item.json.body?.data || {};
const properties = body.properties || {};

const pageId = body.id;

// 2. Extraction du texte MD de CV
const richTextArray = properties.CV?.rich_text || [];
const mdText = richTextArray.map(block => block.plain_text || '').join('');

// 3. Extraction du nom ($name est la ligne après le '#' ou sur la ligne du '#')
let name = 'resume';
const lines = mdText.split(/\r?\n/);
for (let i = 0; i < lines.length; i++) {
  const trimmed = lines[i].trim();
  if (trimmed.startsWith('# ')) {
    const headingText = trimmed.substring(2).trim();
    if (headingText) {
      name = headingText;
    } else if (i + 1 < lines.length) {
      name = lines[i + 1].trim();
    }
    break;
  }
}

// 4. Fonction locale slugify pour nettoyer les chaînes
function slugify(text) {
  return text
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9\-]/g, '');
}

const nameSlug = slugify(name);
const today = new Date().toISOString().split('T')[0];

// 5. Calcul de l'incrément quotidien en inspectant les PDF existants
let maxIncrement = 0;
const pdfFiles = properties.PDF?.files || [];
const prefixPattern = new RegExp("^" + nameSlug + "-resume-" + today + "-(\\d+)\\.pdf$", "i");

for (const fileObj of pdfFiles) {
  const fileName = fileObj.name || '';
  const match = fileName.match(prefixPattern);
  if (match) {
    const inc = parseInt(match[1], 10);
    if (inc > maxIncrement) {
      maxIncrement = inc;
    }
  }
}

const nextIncrement = String(maxIncrement + 1).padStart(2, '0');
const finalFileName = nameSlug + "-resume-" + today + "-" + nextIncrement;
const outputPdf = finalFileName + ".pdf";

// 6. Extraction de Company et JobTitle pour rétrocompatibilité n8n
let company = 'company';
if (properties.Company && properties.Company.select) {
  company = properties.Company.select.name || 'company';
}
let jobTitle = 'job';
const targetProperty = properties.Title || properties["Job Title"];
if (targetProperty && targetProperty.title && targetProperty.title.length > 0) {
  jobTitle = targetProperty.title.plain_text || 'job';
}

// 7. Retour des variables
return [{ 
  json: {
    pageId: pageId,
    company: company,
    jobTitle: jobTitle,
    outputPdf: outputPdf,
    increment: nextIncrement
  }
}];

